  "supportive_card_ids": ["C03", "C15", "C17", "C07", "C13", "C06", "C08"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C15", "C13"],
  "claims": [
    {
      "claim": "Bumetanide, a sulfonamide loop diuretic structurally closest to the query, had absolute oral bioavailability of 95% in patients with cirrhosis (1 mg oral vs IV, n=8), with a second record reporting 95-100%; this is the strongest same-condition, same-class transfer.",
      "card_ids": ["C03", "C15", "C17"]
    },
    {
      "claim": "Tolfenamic acid in cirrhosis showed absolute oral bioavailability of about 100% (100 mg p.o. vs i.v., AUC comparison), with additional patient values of 91%, 113%, and 126%, all far above the 20% threshold.",
      "card_ids": ["C07", "C13", "C18", "C27"]
    },
    {
      "claim": "Isradipine in cirrhosis had systemic availability of about 37% (36.9 ± 16.2%), and a reanalysis reported 0.28 ± 0.14 in cirrhotic patients without shunts; even the lowest cirrhosis record remains above 20%.",
      "card_ids": ["C06", "C08", "C23", "C24"]
    },
    {
      "claim": "The query physicochemical prior (neutral fraction 0, logD -0.84, TPSA 100) is not affirmative evidence of F below 20%; acidic, ionized drugs such as bumetanide and tolfenamic acid show high F in the same cirrhosis condition.",
      "card_ids": ["C03", "C15", "C07", "C13"]
    },
    {
      "claim": "New L4 intestinal absorption, solubility, and permeability records concern unrelated molecules (gliclazide, imatinib, nilotinib, glipizide, mefenamic acid) and mostly surfactant solubility or formulation contexts; none measures the query or a cirrhosis condition, so they do not alter the prediction.",
      "card_ids": ["C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49", "C50", "C51"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49", "C50", "C51"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide-in-cirrhosis bioavailability or AUC record is present in the supplied cards.",
    "L4 records are solubility and absorption statements for other molecules only; none reports F for the query or for cirrhosis.",
    "Query-specific permeability, solubility, and first-pass extraction are not experimentally measured; the low prior is physicochemical only.",
    "Cirrhosis severity and the query dose and formulation are unspecified; transfer from bumetanide, tolfenamic acid, and isradipine relies on structural and condition analogy.",
    "Some low-F records in the broader set (KNI-272 syrup, IQG-607 in mice, slow-dissolving isoniazid tablet) involve different molecules, species, or formulations and cannot be quantitatively transferred."
  ],
  "decision_summary": "Predicted high (F >= 20%): all transferable cirrhosis-context records, bumetanide 95-100%, tolfenamic acid about 100% (91-126%), and isradipine 28-37%, are above threshold. New L4 intestinal absorption and solubility records are not absolute F measurements and concern unrelated molecules, so they do not change the decision. The physicochemical low prior is not affirmative evidence of F below 20%, and low-F records come from unrelated molecules, species, or formulations. Confidence remains high; revision kept."
}

